{"source": "def investigate(context, acquire):
    receipts = acquire("history")

    def simulate(mode, chan, trig, actions):
        committed = {}
        pending = {"main": None, "other": None}
        changes_main = 0
        total_main = 0
        total_other = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                pending[conn] = dict(committed)
            elif op == "commit":
                if pending[conn] is not None:
                    committed.clear()
                    committed.update(pending[conn])
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None
            elif op == "put":
                key = act["key"]
                value = act["value"]
                if pending[conn] is not None:
                    view = pending[conn]
                else:
                    view = committed
                existed = key in view
                inserted = False
                if mode == "ignore":
                    if not existed:
                        view[key] = value
                        inserted = True
                        ch = 1
                    else:
                        ch = 0
                elif mode == "replace":
                    view[key] = value
                    inserted = True
                    ch = 1
                else:
                    if existed:
                        view[key] = value
                        ch = 1
                    else:
                        view[key] = value
                        inserted = True
                        ch = 1
                if conn == "main":
                    changes_main = ch
                    total_main += ch
                    if trig and inserted:
                        total_main += 1
                else:
                    total_other += ch
                    if trig and inserted:
                        total_other += 1
            elif op == "update":
                key = act["key"]
                value = act["value"]
                if pending[conn] is not None:
                    view = pending[conn]
                else:
                    view = committed
                if key in view:
                    view[key] = value
                    ch = 1
                else:
                    ch = 0
                if conn == "main":
                    changes_main = ch
                    total_main += ch
                else:
                    total_other += ch
            elif op == "delete":
                key = act["key"]
                if pending[conn] is not None:
                    view = pending[conn]
                else:
                    view = committed
                if key in view:
                    del view[key]
                    ch = 1
                else:
                    ch = 0
                if conn == "main":
                    changes_main = ch
                    total_main += ch
                else:
                    total_other += ch

        count = len(committed)
        total_sum = sum(committed.values())
        if chan == "changes":
            channel = changes_main
        elif chan == "total":
            channel = total_main
        else:
            channel = total_main + total_other
        return channel, count, total_sum

    modes = ["ignore", "replace", "upsert"]
    chans = ["changes", "total", "total_both"]
    trigs = [False, True]

    candidates = []
    for mode in modes:
        for chan in chans:
            for trig in trigs:
                ok = True
                for r in receipts:
                    ch, cnt, sm = simulate(mode, chan, trig, r["actions"])
                    obs = r["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((mode, chan, trig))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])

    results = set()
    for mode, chan, trig in candidates:
        ch, cnt, sm = simulate(mode, chan, trig, actions)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Predicts channel, committed_count, or committed_sum for a fresh action sequence by simulating all 18 family members (put mode x channel x trigger) and keeping those consistent with calibration receipts; resolves only when all consistent candidates agree.", "lesson": "Replaced the nonlocal-based simulator with a self-contained one that reads/writes committed and pending dicts directly. The receipts show put on existing key yields channel 2 with committed_sum 2, indicating REPLACE or UPSERT (not IGNORE). The rollback receipt shows channel 2 with committed_sum 1, meaning the first put contributed 1 to channel and the rolled-back put contributed 1, consistent with total_changes or changes() where the second put still counted. The other-connection receipt shows channel 2, so channel includes other connection's changes (total_both) or the second put on other connection counted. The begin/put/put/commit receipt shows channel 2 with committed_sum 47, meaning two puts inside transaction each counted 1, and final value 47 (REPLACE or UPSERT). These narrow candidates; the simulator generalizes to new sequences."}
